-- 하나만 고르면 그 타입이다

@Test
void 하나() {
    em.clear();
    Long count = queryFactory
            .select(member.count())
            .from(member)
            .fetchOne();
    System.out.println("타입: " + count.getClass().getSimpleName());
    System.out.println("값:   " + count);
}

