-- Tuple 의 타입을 본다

@Test
void 튜플_타입() {
    em.clear();
    Tuple t = queryFactory
            .select(member.count(), member.age.avg())
            .from(member).fetchOne();

    System.out.println("Tuple:  " + t.getClass().getSimpleName());
    System.out.println("count:  " + t.get(member.count()).getClass()
            .getSimpleName());
    System.out.println("avg:    " + t.get(member.age.avg()).getClass()
            .getSimpleName());
    System.out.println("크기:   " + t.size());
}

Tuple:  QTuple
count:  Long
avg:    Double
크기:   2

--   각 자리가 제 타입을 안다
--   avg 는 Double 이다


-- 인덱스로도 읽힌다

@Test
void 인덱스() {
    em.clear();
    Tuple t = queryFactory
            .select(member.count(), member.age.avg())
            .from(member).fetchOne();

    System.out.println("0: " + t.get(0, Long.class));
    System.out.println("1: " + t.get(1, Double.class));
}

0: 10
1: 23.5

--   ⑭ 8.6절의 Object[] 와 같아진다
--   표현식으로 읽는 게 낫다


-- 빈 결과에서

@Test
void 빈_결과() {
    em.clear();
    Tuple t = queryFactory
            .select(member.count(),
                    member.age.sum(),
                    member.age.avg(),
                    member.age.max())
            .from(member)
            .where(member.age.gt(999))
            .fetchOne();

    System.out.println("count: " + t.get(member.count()));
    System.out.println("sum:   " + t.get(member.age.sum()));
    System.out.println("avg:   " + t.get(member.age.avg()));
    System.out.println("max:   " + t.get(member.age.max()));
}

