-- 원시 타입으로 받으면

@Test
void 언박싱() {
    em.clear();
    try {
        int sum = queryFactory
                .select(member.age.sum())
                .from(member)
                .where(member.age.gt(999))
                .fetchOne();
        System.out.println("sum: " + sum);
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

Hibernate: select sum(m1_0.age) from member m1_0 where m1_0.age>?
예외: NullPointerException

--   null 을 int 에 넣으려다 터졌다


-- coalesce 로 막는다

@Test
void coalesce() {
    em.clear();
    int sum = queryFactory
            .select(member.age.sum().coalesce(0))
            .from(member)
            .where(member.age.gt(999))
            .fetchOne();
    System.out.println("sum: " + sum);
}

