-- count 두 가지

@Test
void count_두_가지() {
    em.clear();
    Tuple t = queryFactory
            .select(member.count(),
                    member.team.count(),
                    member.team.countDistinct())
            .from(member)
            .fetchOne();

    System.out.println("전체:        " + t.get(member.count()));
    System.out.println("팀 있는 행:  " + t.get(member.team.count()));
    System.out.println("팀 종류:     " + t.get(member.team.countDistinct()));
}

