-- 계산도 된다

@Test
void 계산() {
    em.clear();
    Tuple t = queryFactory
            .select(member.age.sum(),
                    member.age.avg().round(),
                    member.age.max().subtract(member.age.min()))
            .from(member)
            .fetchOne();

    System.out.println("합:   " + t.get(member.age.sum()));
    System.out.println("반올림 평균: " + t.get(member.age.avg().round()));
    System.out.println("폭:   " +
            t.get(member.age.max().subtract(member.age.min())));
}

